 *	struct ripemd160_ctx ctx = RIPEMD160_INIT;
 *
 *	for (i = 0; arr[i]; i++)
 *		ripemd160_update(&ctx, arr[i], strlen(arr[i]));
 *	ripemd160_done(&ctx, hash);
 * }
